<script setup lang="ts">import { computed,ref } from 'vue';import { Delete } from '@element-plus/icons-vue';import type { CartLine } from '@ygh/web-shared';import PageHeader from '@/components/PageHeader.vue';const lines=ref<CartLine[]>([{skuId:'10001',name:'粤西高州桂味荔枝礼盒',specifications:{净重:'2.5kg',等级:'特级'},price:'128.00',quantity:1,selected:true,stock:186},{skuId:'10003',name:'澳门杏仁饼传统工艺礼盒',specifications:{净含量:'480g'},price:'69.90',quantity:2,selected:true,stock:320}]);const total=computed(()=>lines.value.filter(x=>x.selected).reduce((s,x)=>s+Number(x.price)*x.quantity,0).toFixed(2));const selected=computed(()=>lines.value.filter(x=>x.selected).length);function selectAll(value:unknown){lines.value.forEach(line=>line.selected=Boolean(value))};</script>
<template><PageHeader title="购物车" description="确认商品、规格与数量后进入订单预览。库存和价格将在服务端重新校验。"/><div class="paper-card cart"><div class="cart-head"><el-checkbox :model-value="selected===lines.length" @change="selectAll">全选</el-checkbox><span>商品信息</span><span>单价</span><span>数量</span><span>小计</span><span>操作</span></div><div v-for="line in lines" :key="line.skuId" class="cart-line"><el-checkbox v-model="line.selected"/><div class="goods"><div class="thumb">{{line.name.slice(0,1)}}</div><div><b>{{line.name}}</b><small>{{Object.entries(line.specifications).map(([k,v])=>`${k} ${v}`).join(' · ')}}</small></div></div><span>¥{{line.price}}</span><el-input-number v-model="line.quantity" :min="1" :max="line.stock" size="small"/><b class="price">¥{{(Number(line.price)*line.quantity).toFixed(2)}}</b><el-button text :icon="Delete" @click="lines=lines.filter(x=>x.skuId!==line.skuId)"/></div><div v-if="!lines.length" class="empty-state">购物车还是空的，去商城挑选商品吧。</div></div><div class="checkout-bar paper-card"><span>已选择 <b>{{selected}}</b> 件商品</span><div>合计：<strong>¥{{total}}</strong><small>不含真实运费</small></div><el-button size="large" type="primary" :disabled="!selected" @click="$router.push('/workspace/checkout')">去结算</el-button></div></template>
<style scoped>.cart{overflow:hidden}.cart-head,.cart-line{display:grid;grid-template-columns:45px minmax(280px,1fr) 100px 150px 110px 60px;align-items:center;padding:15px 20px}.cart-head{background:#edf2ed;color:var(--muted);font-size:12px}.cart-line{border-top:1px solid var(--line);font-size:13px}.goods{display:flex;align-items:center;gap:12px}.goods b,.goods small{display:block}.goods small{margin-top:5px;color:var(--muted)}.thumb{width:58px;height:58px;display:grid;place-items:center;background:var(--jade-soft);color:var(--jade);font:700 22px serif}.checkout-bar{display:flex;align-items:center;justify-content:flex-end;gap:30px;margin-top:16px;padding:15px 20px}.checkout-bar>span{margin-right:auto}.checkout-bar strong,.checkout-bar small{display:block;text-align:right}.checkout-bar strong{color:var(--cinnabar);font-size:22px}.checkout-bar small{color:var(--muted)}@media(max-width:850px){.cart{overflow:auto}.cart-head,.cart-line{min-width:850px}}</style>
